def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    import heapq

    if not jobs:
        return 0

    times = sorted({t for start, end, _ in jobs for t in (start, end)})
    index = {t: i for i, t in enumerate(times)}
    n = len(times)
    graph = [[] for _ in range(n)]

    def add_edge(u, v, capacity, cost):
        graph[u].append([v, len(graph[v]), capacity, cost])
        graph[v].append([u, len(graph[u]) - 1, 0, -cost])

    for u in range(n - 1):
        add_edge(u, u + 1, k, 0)

    for start, end, pay in jobs:
        add_edge(index[start], index[end], 1, -pay)

    # Initial shortest-path potentials: all usable edges point forward.
    potential = [0] * n
    for u in range(n):
        for v, _, capacity, cost in graph[u]:
            if capacity and potential[u] + cost < potential[v]:
                potential[v] = potential[u] + cost

    total_pay = 0
    flow = 0
    infinity = float("inf")

    while flow < k:
        distance = [infinity] * n
        parent = [None] * n
        distance[0] = 0
        heap = [(0, 0)]

        while heap:
            current_distance, u = heapq.heappop(heap)
            if current_distance != distance[u]:
                continue

            for edge_index, (v, _, capacity, cost) in enumerate(graph[u]):
                if capacity == 0:
                    continue
                candidate = (
                    current_distance + cost + potential[u] - potential[v]
                )
                if candidate < distance[v]:
                    distance[v] = candidate
                    parent[v] = (u, edge_index)
                    heapq.heappush(heap, (candidate, v))

        path_cost = distance[-1] + potential[-1] - potential[0]
        if path_cost >= 0:
            break

        for u in range(n):
            if distance[u] != infinity:
                potential[u] += distance[u]

        amount = k - flow
        v = n - 1
        while v:
            u, edge_index = parent[v]
            amount = min(amount, graph[u][edge_index][2])
            v = u

        v = n - 1
        while v:
            u, edge_index = parent[v]
            edge = graph[u][edge_index]
            edge[2] -= amount
            graph[v][edge[1]][2] += amount
            v = u

        flow += amount
        total_pay -= amount * path_cost

    return total_pay
